#!/usr/bin/env node

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

function main() {
  const args = process.argv.slice(2);
  if (args.includes('--help') || args.includes('-h')) {
    console.log(`
Usage: node city-voice-demo.js --problem <problem-id>

Example: node city-voice-demo.js --problem "failure-taxonomy"

Outputs presentation-ready markdown with:
- EXECUTIVE SUMMARY
- KEY AGREEMENTS  
- KEY DISAGREEMENTS
- BLIND SPOTS
`);
    process.exit(0);
  }

  const problemIndex = args.indexOf('--problem');
  if (problemIndex === -1 || !args[problemIndex + 1]) {
    console.error('Error: --problem argument required');
    console.error('Example: node city-voice-demo.js --problem "failure-taxonomy"');
    process.exit(1);
  }
  const problem = args[problemIndex + 1];

  // Run city-voice.js
  try {
    execSync(`node .fastops/city-voice.js --problem "${problem}"`, { stdio: 'pipe' });
  } catch (e) {
    // city-voice may exit with non-zero but still produce output
  }

  // Find latest voice artifact
  const voiceFiles = fs.readdirSync('.fastops')
    .filter(f => f.startsWith('_voice-') && f.endsWith('.json'))
    .sort()
    .reverse();

  if (voiceFiles.length === 0) {
    console.error('Error: No voice artifact found');
    process.exit(1);
  }

  const latestFile = path.join('.fastops', voiceFiles[0]);
  let data;
  try {
    data = JSON.parse(fs.readFileSync(latestFile, 'utf8'));
  } catch (e) {
    console.error(`Error parsing ${latestFile}:`, e.message);
    process.exit(1);
  }

  // Extract converged voice
  const converged = data.converged_voice || data.consensus || '';

  // Extract agreements (assuming structure)
  const agreements = data.agreements || data.key_agreements || [];

  // Extract disagreements
  const disagreements = data.disagreements || data.key_disagreements || [];

  // Extract blind spots
  const blindSpots = data.blind_spots || data.unexplored_angles || [];

  // Format output
  const output = `
# VOICE ANALYSIS: ${problem}

## EXECUTIVE SUMMARY
${converged.split('\n').map(line => line.trim()).filter(line => line).join(' ')}

## KEY AGREEMENTS
${agreements.map(item => `- ${typeof item === 'string' ? item : JSON.stringify(item)}`).join('\n') || '- None identified'}

## KEY DISAGREEMENTS
${disagreements.map(item => {
  const text = typeof item === 'string' ? item : item.text || JSON.stringify(item);
  const models = item.models || item.disagreeing_models || ['multiple models'];
  return `- ${text} (${models.join(', ')})`;
}).join('\n') || '- None identified'}

## BLIND SPOTS
${blindSpots.map(item => `- ${typeof item === 'string' ? item : JSON.stringify(item)}`).join('\n') || '- None identified'}
`;

  console.log(output.trim());
}

if (require.main === module) {
  main();
}

